// Emulator-only options for the `demo-vvu-campus-safety` project, used when
// running with `--dart-define=USE_EMULATOR=true`. The Emulator Suite accepts
// any "demo-" project, so nothing here reaches a real Firebase service.
//
// The real project's options are in firebase_options.dart (generated by
// `flutterfire configure`).

import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show defaultTargetPlatform, kIsWeb, TargetPlatform;

class DemoFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    if (kIsWeb) return web;
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      default:
        throw UnsupportedError(
          'DefaultFirebaseOptions are not configured for this platform.',
        );
    }
  }

  static const FirebaseOptions web = FirebaseOptions(
    apiKey: 'demo-api-key',
    appId: '1:000000000000:web:0000000000000000000000',
    messagingSenderId: '000000000000',
    projectId: 'demo-vvu-campus-safety',
    authDomain: 'demo-vvu-campus-safety.firebaseapp.com',
    storageBucket: 'demo-vvu-campus-safety.appspot.com',
  );

  // The Android SDKs reject a key that isn't shaped like a real one
  // ("AIza" + 35 characters), so this fake key keeps that shape.
  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaDemoKeyForLocalEmulatorUse000000000',
    appId: '1:000000000000:android:0000000000000000000000',
    messagingSenderId: '000000000000',
    projectId: 'demo-vvu-campus-safety',
    storageBucket: 'demo-vvu-campus-safety.appspot.com',
  );
}
